"import re, zlib, sys
data = open(sys.argv[1], 'rb').read()
out = []
for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream', data, re.S):
    s = m.group(1)
    try:
        s = zlib.decompress(s)
    except Exception:
        continue
    if b'BT' not in s:
        continue
    for bt in re.findall(rb'BT(.*?)ET', s, re.S):
        line = []
        for tok in re.findall(rb'\((?:\\.|[^\\)])*\)|<[0-9A-Fa-f]+>|T\*|Td|TD|\'', bt):
            if tok.startswith(b'('):
                t = tok[1:-1]
                t = re.sub(rb'\\([nrtbf()\\])', lambda x: {b'n':b'\n',b'r':b'',b't':b'\t',b'b':b'',b'f':b''}.get(x.group(1), x.group(1)), t)
                t = re.sub(rb'\\(\d{3})', lambda x: bytes([int(x.group(1), 8)]), t)
                line.append(t.decode('latin-1'))
            elif tok.startswith(b'<'):
                h = tok[1:-1]
                try:
                    b = bytes.fromhex(h.decode())
                    line.append(b.decode('utf-16-be') if len(b) % 2 == 0 and b[:1] == b'\x00' else b.decode('latin-1'))
                except Exception:
                    pass
            else:
                line.append(' ')
        out.append(''.join(line))
print('\n'.join(out))
